pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt1, uint256 depositAmt2, uint256 depositAmt3) public {
        // Keep amounts admissible - allow any amount that does not exceed type(uint256).max/3 to avoid overflow in sum tracking
        bound(depositAmt1, 0, type(uint256).max / 3);
        bound(depositAmt2, 0, type(uint256).max / 3);
        bound(depositAmt3, 0, type(uint256).max / 3);

        // Use three different addresses to build up balances
        address alice = address(0x1000);
        address bob = address(0x2000);
        address carol = address(0x3000);

        // Deal ether to each
        vm.deal(alice, depositAmt1);
        vm.deal(bob, depositAmt2);
        vm.deal(carol, depositAmt3);

        // Each deposits
        vm.prank(alice);
        c.deposit{value: depositAmt1}();
        vm.prank(bob);
        c.deposit{value: depositAmt2}();
        vm.prank(carol);
        c.deposit{value: depositAmt3}();

        // After deposits, total ether balance must equal sum of individual tracked balances
        assertTrue(address(c).balance == c.balances(alice) + c.balances(bob) + c.balances(carol));
    }
}

