pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint256 attackerChoice) public {
        // Bound to reasonable values to prevent overflow and ensure usable ranges
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, type(uint128).max);
        attackerChoice = bound(attackerChoice, 1, 2);

        // Deposit to set up some balance
        vm.deal(address(this), depositAmount * 2);
        c.deposit{value: depositAmount}();

        // Use a re-entrant attacker as the counterparty so the fuzzer can explore reentrancy depth.
        // The attacker's receive() will call withdraw again if it chose depth 2, else don't re-enter.
        ReentrantAttacker attacker = new ReentrantAttacker(c, withdrawAmount, attackerChoice);

        // Give the attacker enough balance in c and some ether for fees, then start acting as attacker
        vm.deal(address(attacker), depositAmount);
        vm.startPrank(address(attacker));
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = c.balances(address(attacker));

        // Perform the withdraw that may re-enter
        c.fallback_withdraw(withdrawAmount);
        vm.stopPrank();

        // After the call, for any non-reverting execution, the attacker's ending balance must be
        // exactly balanceBefore minus (withdrawAmount * number_of_successful_transfers).
        // In the reference, at most one transfer succeeds because balance is deducted after transfer;
        // in the buggy version, deduction before transfer can allow multiple successful transfers
        // if reentrancy is triggered, leaving ending balance < balanceBefore - withdrawAmount.
        uint256 endingBalance = c.balances(address(attacker));
        assertTrue(endingBalance >= balanceBefore - withdrawAmount);
    }
}

contract ReentrantAttacker {
    C public c;
    uint256 public amount;
    uint256 public count;
    uint256 public choice;

    constructor(C _c, uint256 _amount, uint256 _choice) {
        c = _c;
        amount = _amount;
        choice = _choice;
    }

    function fallback_withdraw(uint256 _amount) external payable {
        c.withdraw(_amount);
    }

    receive() external payable {
        if (choice == 2 && count < 1) {
            count++;
            c.withdraw(amount);
        }
    }
}

